#!/usr/bin/env bash
# Step 5: build the whole project (all default targets, ~184k modules).
#
# Takes many hours (reference: 7 h on 128 vCPU; expect 11-14 h on 32 cores).
# Run it detached:  scripts/tools/in-tmux.sh scripts/05-build.sh
# Do not edit this file while it runs (bash reads scripts incrementally).
#
# If a module fails with "failed to read file '....olean'" although that file exists,
# vm.max_map_count is too low (see need_max_map_count in lib.sh); raise it and re-run.
# Re-running after an interruption (even a reboot) resumes where Lake stopped: finished
# modules are kept in .lake/build and skipped; only modules in flight are rebuilt. The
# previous build.log is kept with a timestamp; the monitor CSV is appended to.
#
# Outputs: $OUT/build.log(.zst)  full Lake output
#          $OUT/build-monitor.csv disk/memory/progress every 5 minutes
#          $OUT/build-summary.txt
source "$(dirname "$0")/lib.sh"
need_toolchain
need_project
need_max_map_count
log_to 05-build.log

[[ -d "$PROJ/.lake/packages/mathlib" ]] || die "dependencies missing; run scripts/04-fetch-deps.sh"
free_gb=$(( $(df -Pk "$WORKDIR" | awk 'NR==2 {print $4}') / 1000 / 1000 ))
(( free_gb >= 200 )) || die "only ${free_gb} GB free"
log "free disk ${free_gb} GB; JOBS=$JOBS; toolchain $(lean --version | cut -d, -f1)"

blog="$OUT/build.log"
[[ -f "$blog" ]] && mv "$blog" "$OUT/build.$(date -u +%Y%m%dT%H%M%SZ).log"
start_monitor "$OUT/build-monitor.csv" 300 "$blog"
trap stop_monitor EXIT

start=$(date -u +%s)
log "lake build started"
# On Ctrl-C/TERM, Lake (in the same process group) stops; this script must carry on
# and still write its summary and exit status instead of dying with it.
trap 'echo "[interrupted; finishing up]"' INT TERM
set +e
(cd "$PROJ" && LEAN_NUM_THREADS="$JOBS" lake --no-ansi --keep-toolchain build) > "$blog" 2>&1
rc=$?
set -e
end=$(date -u +%s)
stop_monitor

dur=$(( end - start ))
last=$(grep -oE '\[[0-9]+/[0-9]+\]' "$blog" | tail -1 || true)
{
  echo "exit status:     $rc"
  echo "started (UTC):   $(date -u -d @"$start" +%FT%TZ)"
  echo "finished (UTC):  $(date -u -d @"$end" +%FT%TZ)"
  printf 'duration:        %dh %02dm\n' $((dur / 3600)) $((dur % 3600 / 60))
  echo "last progress:   $last"
  echo "error lines:     $(grep -c 'error:' "$blog" || true)"
  echo "warning lines:   $(grep -c 'warning:' "$blog" || true)"
  echo "failed jobs:     $(grep -cE '^✖|^error: build failed' "$blog" || true)"
  echo "final line:      $(tail -1 "$blog")"
  echo "disk after:      $(df -h "$WORKDIR" | awk 'NR==2 {print $3" used, "$4" free"}')"
  echo "size of .lake:   $(du -sh "$PROJ/.lake" | cut -f1)"
  echo "machine:         $(nproc) CPUs, $(free -g | awk '/^Mem:/ {print $2}') GiB RAM, $(uname -m), JOBS=$JOBS"
} | tee "$OUT/build-summary.txt"

log "compressing build log"
zstd -q -T0 -10 -f "$blog" && ls -l "$blog.zst"

if (( rc == 0 )); then ok "lake build succeeded"; else bad "lake build failed (exit $rc); see $blog"; fi
finish
